actions.script:
import java.time.LocalDate
if (!ec.user.isInGroup("ADMIN")) { ec.message.addError("Access denied."); return }
def sub = ec.entity.find("zenith.erp.saas.SaasSubscription").condition("subscriptionId", subscriptionId).one()
if (sub == null) { ec.message.addError("Subscription not found."); return }
if (!(sub.statusId in ['SubActive','SubTrial'])) {
    ec.message.addError("Only an Active or Trial subscription can be prepared for proration testing."); return
}
def subTenant = ec.entity.find("zenith.erp.saas.SaasTenant").condition("tenantId", sub.tenantId).one()
if (subTenant?.organizationPartyId == '100000') {
    ec.message.addError("The flagship live tenant (MARUTHI) is protected — pick a test tenant."); return
}
if (ec.entity.find('zenith.erp.saas.SaasTenantConfig').condition('tenantId',sub.tenantId)
        .condition('configKey','MANUAL_PLAN_SUBSCRIPTION').one()?.configValue) {
    ec.message.addError('Use Tenant Plans to manage this manual assignment.'); return
}
long cycleDays = (sub.billingCycle == 'Yearly') ? 365L : 30L
long dRem
try { dRem = Long.parseLong((daysRemaining ?: '').toString().trim()) }
catch (e) { ec.message.addError("Days remaining must be a whole number."); return }
if (dRem < 1) { ec.message.addError("Days remaining must be at least 1 (keeps the renewal date in the future)."); return }
if (dRem > cycleDays) dRem = cycleDays
def today = LocalDate.now()
def newStart = java.sql.Date.valueOf(today.minusDays(cycleDays - dRem))
def newRenew = java.sql.Date.valueOf(today.plusDays(dRem))
// Guarantee a SINGLE active subscription so the proration basis is unambiguous. change#Plan picks
// the "current" sub via orderBy(-startDate) over SubActive rows; if a tenant carried more than one
// Active/Trial sub (e.g. an upgrade during trial leaves the trial behind), that pick is ambiguous
// and an upgrade can net to zero. Expire every OTHER Active/Trial sub for this tenant, make the
// chosen one Active + mid-cycle, and sync the tenant's plan to it. Now exactly one active sub exists.
def _others = ec.entity.find("zenith.erp.saas.SaasSubscription")
    .condition("tenantId", sub.tenantId)
    .condition("statusId", "in", ["SubActive","SubTrial"]).list()
int _expired = 0
_others.each { o ->
    if (o.subscriptionId != sub.subscriptionId) {
        ec.service.sync().name("update#zenith.erp.saas.SaasSubscription")
            .parameters([subscriptionId: o.subscriptionId, statusId: 'SubExpired']).call()
        _expired++
    }
}
ec.service.sync().name("update#zenith.erp.saas.SaasSubscription")
    .parameters([subscriptionId: sub.subscriptionId, statusId: 'SubActive',
                 startDate: newStart, renewalDate: newRenew]).call()
ec.service.sync().name("update#zenith.erp.saas.SaasTenant")
    .parameters([tenantId: sub.tenantId, planId: sub.planId]).call()
ec.service.sync().name("create#zenith.erp.saas.SaasAuditLog")
    .parameters([tenantId: sub.tenantId, eventType: 'CYCLE_ADJUST', eventDate: ec.user.nowTimestamp,
        userId: ec.user.userId,
        description: 'Prepared for proration testing: sole Active sub on ' + sub.planId + ', ' + dRem + '/' +
            cycleDays + ' days remaining (start ' + newStart + ', renewal ' + newRenew + ')' +
            (_expired > 0 ? '; expired ' + _expired + ' other active/trial sub(s)' : '')]).call()
ec.message.addMessage("Subscription ${sub.subscriptionId} is now the single Active subscription (plan ${sub.planId}) " +
    "with ${dRem} of ${cycleDays} days remaining${_expired > 0 ? ' (' + _expired + ' other sub(s) expired)' : ''}. " +
    "Now upgrade this tenant's plan to a higher one (Tenants → open the tenant → Change Plan) to generate the prorated invoice.")
